// Generated by Hive v{{HIVE_VERSION}}. Tool registration shared by every transport.
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import definitions from './tools.json' with { type: 'json' };
import { toObject } from './schema.js';
import { execute, type AuthContext } from './adapter.js';
import { loadPolicy, allowed } from './policy.js';
import { record } from './log.js';
import type { Tool } from './types.js';
export const tools = definitions as unknown as Tool[];
export type Context = { auth?: AuthContext; userAgent?: string; transport: 'http' | 'stdio' };
export const list = (value?: string) =>
  (value ?? '')
    .split(',')
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
// Shared by the local server (server.ts) and the hosted function (vercel.ts).
export function createMcp(context: Context) {
  const server = new McpServer({ name: 'hive-generated-mcp', version: '{{HIVE_VERSION}}' });
  const policy = loadPolicy();
  if (policy.error) console.error(`Hive MCP: ${policy.error}`);
  // Tools denied by .hive/policy.json are not listed; calls are re-checked for long-lived stdio.
  for (const tool of tools.filter((t) => allowed(policy, t))) {
    server.registerTool(
      tool.name,
      {
        description: tool.description,
        inputSchema: toObject(tool.inputSchema),
        annotations: {
          readOnlyHint: tool.risk === 'read',
          destructiveHint: tool.risk === 'destructive',
          openWorldHint: true,
        },
      },
      async (input: Record<string, unknown>) => {
        const started = Date.now();
        const base = {
          time: new Date(started).toISOString(),
          tool: tool.name,
          risk: tool.risk,
          transport: context.transport,
          userAgent: context.userAgent,
        };
        if (!allowed(loadPolicy(), tool)) {
          record({ ...base, outcome: 'denied', durationMs: 0 }, input);
          return {
            isError: true,
            content: [
              {
                type: 'text' as const,
                text: `Tool ${tool.name} is disabled by .hive/policy.json.`,
              },
            ],
          };
        }
        const observed: { status?: number } = {};
        try {
          const result = await execute(tool, input, context.auth, undefined, observed);
          record(
            {
              ...base,
              outcome: result.isError ? 'app_error' : 'ok',
              status: observed.status,
              durationMs: Date.now() - started,
            },
            input,
          );
          return result;
        } catch {
          record(
            {
              ...base,
              outcome: 'failed',
              status: observed.status,
              durationMs: Date.now() - started,
            },
            input,
          );
          return {
            isError: true,
            content: [
              {
                type: 'text' as const,
                text: 'Application request failed. Check the application URL, availability, credentials, timeout, and generated adapter configuration.',
              },
            ],
          };
        }
      },
    );
  }
  return server;
}
